import hashlib, hmac
SECRET = b'signature-test-secret'
def seal(payload):
    return hmac.new(SECRET, payload.encode(), hashlib.sha256).hexdigest()
EVENTS = [('s-1', 'order shipped', seal('order shipped'), False), ('s-2', 'order shipped', 'badbad', False), ('s-1', 'order shipped', seal('order shipped'), True)]
for eid, payload, sig, replay in EVENTS:
    if sig != seal(payload):
        print(eid, '-> REJECTED (bad seal)')
    elif replay:
        print(eid, '-> ACKNOWLEDGED, NOT REPROCESSED (replay)')
    else:
        print(eid, '-> VERIFIED, PROCESSED:', payload)

